"""Config parsing helpers."""


def parse_setting(raw: str) -> int:
    """Parse a positive integer setting."""
    value = int(raw)
    if value <= 0:
        raise ValueError("must be positive")
    return value


def parse_timeout(text: str) -> int:
    """Parse a timeout in seconds; raises ValueError for non-positive input."""
    value = int(text)
    if value <= 0:
        raise ValueError("timeout must be positive")
    return value

